// session.ts
import { randomUUID } from 'crypto';
import fs from 'fs';
import path from 'path';

const SESSION_FILE = '.agent-session.json';

export type Message = {
  role: 'system' | 'user' | 'assistant' | 'tool';
  content: string | null;
  reasoning?: string;
  toolCallId?: string;
  toolCalls?: Array<{
    id: string;
    type: 'function';
    function: { name: string; arguments: string };
  }>;
};

export type SessionMeta = {
  id: string;
  cwd: string;
  createdAt: string;
  lastActive: string;
};

const SESSIONS_DIR = path.join(process.cwd(), '.agent-sessions');
const INDEX_FILE = path.join(SESSIONS_DIR, 'index.json');

function ensureDir() {
  if (!fs.existsSync(SESSIONS_DIR)) {
    fs.mkdirSync(SESSIONS_DIR, { recursive: true });
  }
}
export function listSessions(): SessionMeta[] {
  ensureDir();
  if (!fs.existsSync(INDEX_FILE)) return [];
  try {
    return JSON.parse(fs.readFileSync(INDEX_FILE, 'utf8'));
  } catch {
    return [];
  }
}
export function getLatestSessionId(): string | null {
  const sessions = listSessions();
  if (sessions.length === 0) return null;
  sessions.sort((a, b) => new Date(b.lastActive).getTime() - new Date(a.lastActive).getTime());
  if(!sessions || sessions.length === 0) {
    console.log(`No Sessions found, creating a new one.`);
    return null;
  }
  return sessions[0].id;
}

export function loadSession(sessionId: string): Message[] {
  ensureDir();
  const sessionPath = path.join(SESSIONS_DIR, `${sessionId}.json`);
  if (!fs.existsSync(sessionPath)) return [];
  try {
    return JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
  } catch {
    return [];
  }
}

export function saveSession(sessionId: string, messages: Message[]) {
  ensureDir();
  const sessionPath = path.join(SESSIONS_DIR, `${sessionId}.json`);
  fs.writeFileSync(sessionPath, JSON.stringify(messages, null, 2));

  // Update Index
  const sessions = listSessions();
  const idx = sessions.findIndex(s => s.id === sessionId);
  const now = new Date().toISOString();

  if (idx >= 0) {
    sessions[idx].lastActive = now;
  } else {
    sessions.push({
      id: sessionId,
      cwd: process.cwd(),
      createdAt: now,
      lastActive: now,
    });
  }

  fs.writeFileSync(INDEX_FILE, JSON.stringify(sessions, null, 2));
}
export function createNewSessionId(): string {
  return randomUUID();
}

import { MODEL, COMPACTION_THRESHOLD_TOKENS, COMPACTION_KEEP_RECENT } from "./constant.js";
import { client } from "./openrouter.js";
import type { Message } from "./session.js";

export const compactHistoryIfNeeded = async (messages: Message[]): Promise<Message[]> => {
  const estimatedTokens = JSON.stringify(messages).length / 4;
  console.log(`[compaction check] ~${Math.round(estimatedTokens)} tokens (threshold: ${COMPACTION_THRESHOLD_TOKENS})`);

  if (estimatedTokens < COMPACTION_THRESHOLD_TOKENS) return messages;

  const systemMsg: Message = messages.find(m => m.role === 'system') ?? messages[0] ?? {
    role: "system",
    content: "You are FORGE, an expert autonomous software engineering agent operating directly in the user's local terminal environment. Your goal is to solve programming tasks, fix bugs, refactor code, and analyze repositories efficiently and safely.\n\n### OPERATIONAL PRINCIPLES & MINDSET\n1. **Be Concise & Direct:** You operate in a command-line interface. Minimize fluff, polite pleasantries, and unnecessary conversational filler. Focus on action and execution.\n2. **Context-Aware:** You are provided with continuous session history across execution steps. Maintain high coherence with previous user instructions and tool outputs.\n3. **Verify Before Action:** Inspect the existing codebase structure before writing code or running shell commands. Do not guess file paths, implementation details, or framework configurations.\n\n### TOOL USAGE PROTOCOL\n1. **Gather Context First:** Use read-only, discovery tools (e.g., file readers, search/grep, directory listings) to understand the project context before performing modifications.\n2. **Batch & Sequence Logically:** Execute tools in logical, dependent order. Inspect files -> Modify code -> Run tests/lints to verify changes.\n3. **Handle Errors Gracefully:** If a tool execution fails or a command throws an error, do not panic or repeat the exact same failing action. Read the stderr/error log carefully, adjust your strategy, and attempt a corrective step.\n4. **Tool Restrictions:** Never execute destructive or non-reversible actions (e.g., recursive deletions, git hard resets, system-level package updates) without explicit confirmation.\n\n### CODE MODIFICATION & QUALITY STANDARDS\n1. **Minimal, Precise Changes:** Prefer targeted edits over rewriting whole files unless requested or necessary. Do not delete unrelated comments, dead code, or existing functionality without reason.\n2. **Adhere to Code Conventions:** Match the existing codebase style, naming conventions, formatting rules, and type strictness (e.g., TypeScript interfaces, ESLint guidelines).\n3. **Self-Correction & Verification:** After making edits, verify your work whenever tools permit (e.g., run standard test suites, build checks, or type checking commands).\n\n### OUTPUT FORMATTING & STYLE\n- Present code blocks with explicit language syntax highlighting tags.\n- Keep technical commentary brief—explain *why* a change was made rather than describing mechanical syntax edits line-by-line.\n- On completing a task, summarize the changes made, the current state of the workspace, and suggest logical next verification steps for the user."
  };

  const recent = messages.slice(-COMPACTION_KEEP_RECENT);
  const toSummarize = messages.slice(1, -COMPACTION_KEEP_RECENT);

  if (toSummarize.length === 0) return messages;

  console.log(`[compaction] compacting ${toSummarize.length} messages...`);

  try {
    const summaryResponse = await client.chat.send({
      chatRequest: {
        model: MODEL,
        messages: [
          {
            role: 'system',
            content: 'Summarize this conversation history concisely. You MUST explicitly state, verbatim or near-verbatim, what the user\'s most recent request/goal was — this is the single most important thing to preserve. Also preserve: file paths touched, key decisions made, and any unresolved sub-tasks. Discard: verbose reasoning, redundant tool output, and repeated file contents already summarized elsewhere.'
          }, { role: 'user', content: JSON.stringify(toSummarize) },
        ],
      },
    });

    const summary = summaryResponse.choices[0].message.content;

    if (!summary) {
      console.log('[compaction] empty summary returned, skipping compaction this round.');
      return messages;
    }

    console.log(`[compaction] done — collapsed ${toSummarize.length} messages into 1.`);

    return [
      systemMsg,
      { role: 'system', content: `[Compacted history — the user's active request is stated below; continue working on it]: ${summary}` },
      ...recent,
    ];
  } catch (err) {
    console.log('[compaction] failed, continuing with uncompacted history:', err);
    return messages;
  }
};

#!/usr/bin/env node

import { tools } from './tools.js';
import { toolExecutors } from './toolHelper.js';
import { saveSession, type Message } from './session.js';
import { client } from './openrouter.js';
import { FALLBACK_MODELS, MAX_ITERATIONS, MODEL, RISKY_TOOLS } from './constant.js';
import { compactHistoryIfNeeded } from './compaction.js';

export type LogEvent =
  | { type: 'reasoning_delta'; content: string }
  | { type: 'tool_call'; name: string; args: any }
  | { type: 'tool_result'; content: string }
  | { type: 'assistant_delta'; content: string }
  | { type: 'info'; content: string }
  | { type: 'sub_agent'; content: string };

export type Callbacks = {
  onLog: (event: LogEvent) => void;
  onConfirm: (description: string) => Promise<boolean>;
};

export async function runAgent(sessionId: string, messages: Message[], callbacks: Callbacks): Promise<Message[]> {
  let iterations = 0;

  while (iterations < MAX_ITERATIONS) {
    iterations++;

    messages = await compactHistoryIfNeeded(messages);
    saveSession(sessionId, messages);

    const stream = await client.chat.send({
      chatRequest: { model: MODEL, models: FALLBACK_MODELS, messages, tools, stream: true },
    });

    let content = '';
    let reasoning = '';
    const toolCallsAccumulator: Record<number, { id?: string; name?: string; arguments: string }> = {};

    for await (const chunk of stream as any) {
      const delta = (chunk as any).choices?.[0]?.delta;
      if (!delta) continue;

      if (delta.content) {
        content += delta.content;
        callbacks.onLog({ type: 'assistant_delta', content: delta.content });
      }

      if (delta.reasoning) {
        reasoning += delta.reasoning;
        callbacks.onLog({ type: 'reasoning_delta', content: delta.reasoning });

      }

      if (delta.toolCalls) {
        for (const tc of delta.toolCalls) {
          const idx = tc.index ?? 0;
          if (!toolCallsAccumulator[idx]) toolCallsAccumulator[idx] = { arguments: '' };
          if (tc.id) toolCallsAccumulator[idx].id = tc.id;
          if (tc.function?.name) toolCallsAccumulator[idx].name = tc.function.name;
          if (tc.function?.arguments) toolCallsAccumulator[idx].arguments += tc.function.arguments;
        }
      }
    }


    const toolCallEntries = Object.values(toolCallsAccumulator);
    const toolCalls =
      toolCallEntries.length > 0
        ? toolCallEntries.map((tc, i) => ({
          id: tc.id ?? `call_${i}`,
          type: 'function' as const,
          function: { name: tc.name!, arguments: tc.arguments },
        }))
        : undefined;

    const message: Message = {
      role: 'assistant',
      content: content || null,
      reasoning: reasoning || undefined,
      toolCalls,
    };

    if (!message.toolCalls || message.toolCalls.length === 0) {
      messages.push(message);
      saveSession(sessionId, messages);
      return messages;
    }

    messages.push(message);


    const riskyChecks: Array<typeof message.toolCalls[number]> = [];
    const safeCalls: Array<typeof message.toolCalls[number]> = [];


    for (const call of message.toolCalls) {
      if (RISKY_TOOLS.has(call.function.name)) {
        riskyChecks.push(call);
      } else {
        safeCalls.push(call);
      }
    }

    const safeToolsResult = await Promise.all(
      safeCalls.map(async (call) => {
        const args = JSON.parse(call.function.arguments);
        callbacks.onLog({ type: 'tool_call', name: call.function.name, args });

        const executor = toolExecutors[call.function.name];
        if (!executor) {
          return { callId: call.id, content: `ERROR: No executor found for tool: ${call.function.name}` };
        }

        const output = await executor(args);

        if (call.function.name === 'spawn_sub_agent') {
          callbacks.onLog({ type: 'sub_agent', content: 'Sub Agent Completed the Task.' });
        } else {
          callbacks.onLog({ type: 'tool_result', content: output });
        }

        return { callId: call.id, content: output };
      })
    );




















    for (const call of riskyChecks) {
      const args = JSON.parse(call.function.arguments);
      callbacks.onLog({ type: 'tool_call', name: call.function.name, args });

      const executor = toolExecutors[call.function.name];
      if (!executor) {
        messages.push({
          role: 'tool',
          toolCallId: call.id,
          content: `ERROR: No executor found for tool: ${call.function.name}`,
        });
        continue;
      }


      const allowed = await callbacks.onConfirm(`${call.function.name}(${JSON.stringify(args)})`);
      if (!allowed) {
        callbacks.onLog({ type: 'info', content: `Denied: ${call.function.name}` });
        messages.push({ role: 'tool', toolCallId: call.id, content: 'User denied this action.' });
        continue;
      }




      const output = await executor(args);
      callbacks.onLog({ type: 'tool_result', content: output });
      messages.push({ role: 'tool', toolCallId: call.id, content: output });
    }
    for (const { callId, content } of safeToolsResult) {
      messages.push({ role: 'tool', toolCallId: callId, content });
    }
    saveSession(sessionId, messages);
  }

  callbacks.onLog({ type: 'info', content: 'Max iterations reached without a final answer.' });
  saveSession(sessionId, messages);
  return messages;
}

export const AGENT_NAME = 'FORGE';
export const MODEL = 'nvidia/nemotron-3-ultra-550b-a55b:free';
export const MAX_ITERATIONS = 20;
export const RISKY_TOOLS = new Set(['run_bash', 'write_file', 'replace_string_in_file']);
export const SYSTEM_PROMPT = `You are ${AGENT_NAME}, an expert autonomous software engineering agent operating directly in the user's local terminal environment. Your goal is to solve programming tasks, fix bugs, refactor code, and analyze repositories efficiently and safely.

### OPERATIONAL PRINCIPLES & MINDSET
1. **Be Concise & Direct:** You operate in a command-line interface. Minimize fluff, polite pleasantries, and unnecessary conversational filler. Focus on action and execution.
2. **Context-Aware:** You are provided with continuous session history across execution steps. Maintain high coherence with previous user instructions and tool outputs.
3. **Verify Before Action:** Inspect the existing codebase structure before writing code or running shell commands. Do not guess file paths, implementation details, or framework configurations.

### TOOL USAGE PROTOCOL
1. **Gather Context First:** Use read-only, discovery tools (e.g., file readers, search/grep, directory listings) to understand the project context before performing modifications.
2. **Batch & Sequence Logically:** Execute tools in logical, dependent order. Inspect files -> Modify code -> Run tests/lints to verify changes.
3. **Handle Errors Gracefully:** If a tool execution fails or a command throws an error, do not panic or repeat the exact same failing action. Read the stderr/error log carefully, adjust your strategy, and attempt a corrective step.
4. **Tool Restrictions:** Never execute destructive or non-reversible actions (e.g., recursive deletions, git hard resets, system-level package updates) without explicit confirmation.

### CODE MODIFICATION & QUALITY STANDARDS
1. **Minimal, Precise Changes:** Prefer targeted edits over rewriting whole files unless requested or necessary. Do not delete unrelated comments, dead code, or existing functionality without reason.
2. **Adhere to Code Conventions:** Match the existing codebase style, naming conventions, formatting rules, and type strictness (e.g., TypeScript interfaces, ESLint guidelines).
3. **Self-Correction & Verification:** After making edits, verify your work whenever tools permit (e.g., run standard test suites, build checks, or type checking commands).

### OUTPUT FORMATTING & STYLE
- Present code blocks with explicit language syntax highlighting tags.
- Keep technical commentary brief—explain *why* a change was made rather than describing mechanical syntax edits line-by-line.
- On completing a task, summarize the changes made, the current state of the workspace, and suggest logical next verification steps for the user.`;
export const COMPACTION_THRESHOLD_TOKENS = 2000;
export const COMPACTION_KEEP_RECENT = 5;
export const FALLBACK_MODELS = ['nvidia/nemotron-3.5-lightning:free', 'dots-studio/dots-3-note-preview:free', 'poolside/laguna-s-2.1:free'];
export const SUBAGENT_MAX_ITERATIONS = 10; 
export const SUBAGENT_TOOLS = ["read_file", "run_bash"];
